B.aKM=new A.ex("job_templates","TRACK_3","Jobs & Templates","Reusable Job & Checklist Templates",B.R3,"Standardize recurring workflows like Unit Turnovers, Seasonal Winterization, or Smoke Detector Checks.",B.cc9,null,"/job-templates")
